try { require __DIR__.'/app/bootstrap.php'; } catch (Throwable $e) { http_response_code(503); exit('Open EFS setup and check the database connection.'); }
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');
session_name('PETROLPOS_SESSION');session_start();
if(($_SESSION['recovery_epoch']??'')!==(string)$db->setting('recovery_session_epoch',''))unset($_SESSION['user_id']);
if(!isset($_SESSION['user_id'])||time()-(int)($_SESSION['last_activity']??0)>$config['session_minutes']*60||!$db->one('SELECT id FROM users WHERE id=? AND active=1',[$_SESSION['user_id']])){http_response_code(401);exit('Sign in to view this receipt.');}
