function esc($s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function cash(int $v):string{return number_format($v/100,2);}
$local=(new DateTimeImmutable($r['created_at']))->setTimezone(new DateTimeZone($db->setting('timezone','Asia/Colombo')));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EFS · <?=esc($r['receipt_no'])?></title><style>body{font:12px Consolas,monospace;color:#000;background:#eee;margin:20px}article{width:72mm;margin:auto;background:#fff;padding:4mm}h1{font-size:17px;text-align:center;margin:0 0 8px}p{margin:5px 0}.center{text-align:center}hr{border:0;border-top:1px dashed #777;margin:12px 0}table{width:100%;border-collapse:collapse}td{vertical-align:top;padding:6px 0}.right{text-align:right;white-space:nowrap}.total{font-size:18px;font-weight:bold}button{display:block;margin:15px auto;padding:12px 25px;cursor:pointer}small{font-size:10px}@page{size:80mm auto;margin:4mm}@media print{body{background:#fff;margin:0}article{width:auto;padding:0;margin:0}button{display:none}}</style></head><body><button onclick="window.print()">Print receipt</button><article><h1><?=esc($db->setting('station_name'))?></h1><p class="center"><?=nl2br(esc($db->setting('address')))?><br><?=esc($db->setting('phone'))?></p><hr><p><?=esc($r['receipt_no'])?><br><?=esc($local->format('d M Y H:i'))?><br>Operator: <?=esc($r['user_name'])?></p><?php if($r['customer_name']):?><p><?=esc($r['customer_name'])?><br><?=esc($r['registration'])?><br>Indent: <?=esc($r['indent_no'])?></p><?php endif?><hr><table><?php foreach($r['items']as $i):?><tr><td><?=esc($i['description'])?><br><small><?=esc(number_format($i['quantity_milli']/1000,3))?> <?=$i['kind']==='fuel'?'L':'units'?> × <?=cash($i['unit_price_cents'])?></small></td><td class="right"><?=cash($i['line_cents'])?></td></tr><?php endforeach?></table><hr><table><tr class="total"><td><?=esc($db->setting('currency'))?></td><td class="right"><?=cash($r['total_cents'])?></td></tr></table><hr><table><?php foreach($r['payments']as $p):?><tr><td><?=esc(strtoupper($p['method']))?></td><td class="right"><?=cash($p['amount_cents'])?></td></tr><?php endforeach?></table><hr><p class="center"><?=esc($db->setting('receipt_footer'))?></p><p class="center"><small>Ezy Filling System (EFS)<br>Local sales receipt · Keep for your records</small></p></article></body></html>
